WITH parsed AS (SELECT id, service, host, level, latency_ms, context['trace'] AS trace, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, COALESCE(context['region'], 'none') AS region_or_default FROM app_logs WHERE host = 'h2') SELECT *, SUM(latency_ms) OVER (PARTITION BY host) AS host_sum_latency_ms, ROW_NUMBER() OVER (PARTITION BY level ORDER BY retry_count DESC, id) AS event_seq, NTILE(5) OVER (PARTITION BY level, service ORDER BY latency_ms, id) AS latency_ms_bucket, AVG(retry_count) OVER (ORDER BY retry_count, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS retry_count_avg_2 FROM parsed
